from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import Json
from typing import List

app = FastAPI()

@app.post("/test-list")
async def test_list(items: List[str] = Form()):
    return {"items": items}

@app.post("/test-json-list")
async def test_json_list(items: Json[List[str]] = Form()):
    return {"items": items}

client = TestClient(app)

def test_list():
    response = client.post("/test-list", data={"items": ["a", "b"]})
    assert response.status_code == 200
    assert response.json() == {"items": ["a", "b"]}
    print("test_list passed")

def test_json_list():
    response = client.post("/test-json-list", data={"items": '["a", "b"]'})
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"items": ["a", "b"]}
    print("test_json_list passed")

if __name__ == "__main__":
    try:
        test_list()
        test_json_list()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

